pub fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as described): start + sub.len() <= main.len()
    // If violated, we return false to stay safe.
    if start > main.len() || main.len() - start < sub.len() {
        return false;
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

pub fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty subarray always matches.
    if sub.is_empty() {
        return true;
    }
    if sub.len() > main.len() {
        return false;
    }

    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}